/**
* Syncs every linked user; one user's failure doesn't stop the others. Users synced within the last
* `minGapMs` are skipped, so calling the (public) run address repeatedly can't hammer Google.
*/
async function runAll(env, minGapMs = 3e6) {
	const d = db(env);
	const tokens = await d.select("google_tokens", "select=user_id,refresh_token,scopes");
	const statuses = await d.select("sync_status", "select=user_id,time_zone,last_sync_at");
	const out = [];
	for (const t of tokens) {
		const st = statuses.find((s) => s.user_id === t.user_id);
		if (st?.last_sync_at && Date.now() - Date.parse(st.last_sync_at) < minGapMs) {
			out.push({
				user: t.user_id,
				result: "skipped: synced recently"
			});
			continue;
		}
		const tz = st?.time_zone ?? "America/Los_Angeles";
		const now = (/* @__PURE__ */ new Date()).toISOString();
		try {
			const result = await syncUser(env, t.user_id, await tokensFor(env, t.refresh_token, t.scopes), tz);
			await d.upsert("sync_status", [{
				user_id: t.user_id,
				last_sync_at: now,
				last_result: result,
				last_error: null,
				needs_relink: false,
				updated_at: now
			}], "user_id");
			out.push({
				user: t.user_id,
				result
			});
		} catch (e) {
			const relink = e instanceof RelinkNeeded;
			await d.upsert("sync_status", [{
				user_id: t.user_id,
				last_error: e.message,
				needs_relink: relink,
				updated_at: now
			}], "user_id");
			if (relink) await d.remove("google_tokens", `user_id=eq.${t.user_id}`);
			out.push({
				user: t.user_id,
				result: `error: ${e.message}`
			});
		}
	}
	return out;
}
/** Links a user: checks their app sign-in, trades Google's one-time code for background access, and syncs right away. */
async function link(env, appJwt, code, tz) {
	const who = await fetch(`${env.supabaseUrl}/auth/v1/user`, { headers: {
		apikey: env.anonKey,
		Authorization: `Bearer ${appJwt}`
	} });
	if (!who.ok) throw new Error("Not signed in to the app.");
	const userId = (await who.json()).id;
	const g = await exchangeCode(env, code);
	const d = db(env);
	const now = (/* @__PURE__ */ new Date()).toISOString();
	await d.upsert("google_tokens", [{
		user_id: userId,
		refresh_token: g.refreshToken,
		scopes: g.scopes,
		linked_at: now
	}], "user_id");
	await d.upsert("sync_status", [{
		user_id: userId,
		linked_at: now,
		time_zone: tz,
		needs_relink: false,
		last_error: null,
		updated_at: now
	}], "user_id");
	try {
		const result = await syncUser(env, userId, await tokensFor(env, g.refreshToken, g.scopes), tz);
		await d.upsert("sync_status", [{
			user_id: userId,
			last_sync_at: (/* @__PURE__ */ new Date()).toISOString(),
			last_result: result,
			updated_at: (/* @__PURE__ */ new Date()).toISOString()
		}], "user_id");
		return result;
	} catch (e) {
		await d.upsert("sync_status", [{
			user_id: userId,
			last_error: e.message,
			updated_at: (/* @__PURE__ */ new Date()).toISOString()
		}], "user_id");
		throw e;
	}
}
/**
* Syncs only the signed-in user, right now (the app calls this when it opens). Skips when a sync ran in the
* last `minGapMs`, so opening the app repeatedly doesn't hit Google each time.
*/
async function syncMe(env, appJwt, tz, minGapMs = 6e5) {
	const who = await fetch(`${env.supabaseUrl}/auth/v1/user`, { headers: {
		apikey: env.anonKey,
		Authorization: `Bearer ${appJwt}`
	} });
	if (!who.ok) throw new Error("Not signed in to the app.");
	const userId = (await who.json()).id;
	const d = db(env);
	const token = (await d.select("google_tokens", `user_id=eq.${userId}&select=refresh_token,scopes`))[0];
	if (!token) return {
		ran: false,
		result: "not linked"
	};
	const st = (await d.select("sync_status", `user_id=eq.${userId}&select=user_id,time_zone,last_sync_at`))[0];
	if (tz && st && tz !== st.time_zone) {
		await d.upsert("sync_status", [{
			user_id: userId,
			time_zone: tz,
			updated_at: (/* @__PURE__ */ new Date()).toISOString()
		}], "user_id");
		st.time_zone = tz;
	}
	if (st?.last_sync_at && Date.now() - Date.parse(st.last_sync_at) < minGapMs) return {
		ran: false,
		result: "synced recently"
	};
	const now = (/* @__PURE__ */ new Date()).toISOString();
	try {
		const result = await syncUser(env, userId, await tokensFor(env, token.refresh_token, token.scopes), st?.time_zone ?? "America/Los_Angeles");
		await d.upsert("sync_status", [{
			user_id: userId,
			last_sync_at: now,
			last_result: result,
			last_error: null,
			needs_relink: false,
			updated_at: now
		}], "user_id");
		return {
			ran: true,
			result
		};
	} catch (e) {
		const relink = e instanceof RelinkNeeded;
		await d.upsert("sync_status", [{
			user_id: userId,
			last_error: e.message,
			needs_relink: relink,
			updated_at: now
		}], "user_id");
		if (relink) await d.remove("google_tokens", `user_id=eq.${userId}`);
		throw e;
	}
}
/** Stops background sync for the signed-in user and forgets their Google access. */
async function unlink(env, appJwt) {
	const who = await fetch(`${env.supabaseUrl}/auth/v1/user`, { headers: {
		apikey: env.anonKey,
		Authorization: `Bearer ${appJwt}`
	} });
	if (!who.ok) throw new Error("Not signed in to the app.");
	const userId = (await who.json()).id;
	const d = db(env);
	const tokens = await d.select("google_tokens", `user_id=eq.${userId}&select=refresh_token`);
	if (tokens[0]) await fetch(`https://oauth2.googleapis.com/revoke?token=${encodeURIComponent(tokens[0].refresh_token)}`, { method: "POST" }).catch(() => null);
	await d.remove("google_tokens", `user_id=eq.${userId}`);
	await d.upsert("sync_status", [{
		user_id: userId,
		linked_at: null,
		needs_relink: false,
		last_error: null,
		updated_at: (/* @__PURE__ */ new Date()).toISOString()
	}], "user_id");
}
